-- Import from uploaded OSM GeoJSON (overpass-turbo export 2026-08-15). Coordinates = polygon vertex centroid, converted from [lon,lat].
update public.places set osm_id='way/360048241', lat=13.685941, lng=79.349017, coords_verified=true, coords_source='osm', needs_review=false,
  osm_tags='{"alt_name":"Anna Prasada Centre","operator":"Tirumala Tirupati Devastanams","opening_hours":"Mo-Su 08:30-10:30,10:30-16:00,17:00-11:00","addr:street":"North Mada Street","name:kn":"ಅನ್ನಪ್ರಾಸದ ಕೇಂದ್ರ"}'::jsonb where slug='annaprasadam-bhavan';
update public.places set osm_id='way/362777815', lat=13.683243, lng=79.347352, coords_verified=true, coords_source='osm', needs_review=false,
  osm_tags='{"alt_name":"Tirupati Balaji Temple","website":"https://www.tirumala.org/","name:kn":"ತಿರುಪತಿ ಬಾಲಾಜಿ ದೇವಾಲಯ","name:ml":"തിരുമല തിരുപ്പതി ശ്രീ വെങ്കടേശ്വരക്ഷേത്രം","name:ta":"ஸ்ரீ வெங்கடேஸ்வர சுவாமி கோவில்"}'::jsonb where slug='sri-venkateswara-temple';
update public.places set osm_id='way/362927173', lat=13.679158, lng=79.35112, coords_verified=true, coords_source='osm', needs_review=false where slug='cro-office';
update public.places set osm_id='way/1548291853', lat=13.684495, lng=79.347911, coords_verified=true, coords_source='osm', needs_review=false,
  osm_tags='{"name:kn":"ಸ್ವಾಮಿ ಪುಷ್ಕರಿಣಿ","name:ta":"சுவாமி புஷ்கரிணி"}'::jsonb where slug='swami-pushkarini';
update public.places p set name = coalesce((select jsonb_object_agg(substr(key, 6), value) from jsonb_each_text(p.osm_tags) where key ~ '^name:(te|ta|kn|ml|hi|or)$'), '{}'::jsonb) || p.name
  where p.osm_id is not null;
update public.places set needs_review = true where osm_id is null;

on conflict (osm_id) do nothing;